import contextlib
import io
import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import tally  # noqa: E402
from tally.validate import validate_category  # noqa: E402

COMMANDS = {
    "add": lambda c: ["add", "1", c],
    "budget set": lambda c: ["budget", "set", c, "1"],
    "recur add": lambda c: ["recur", "add", "1", c, "--every", "monthly"],
}

BAD = ["", "  ", "Food", "eating out", "café", "food_drinks", "a" * 25]
GOOD = ["food", "car-2", "a" * 24]


class ValidateCategoryTest(unittest.TestCase):
    def test_accepts_valid_names(self):
        for name in GOOD:
            self.assertEqual(validate_category(name), name)
        self.assertEqual(validate_category("  food "), "food")

    def test_rejects_invalid_names(self):
        for name in BAD:
            with self.assertRaises(ValueError):
                validate_category(name)


class CommandsShareRulesTest(unittest.TestCase):
    def setUp(self):
        self.old_cwd = os.getcwd()
        self.tmp = tempfile.TemporaryDirectory()
        os.chdir(self.tmp.name)

    def tearDown(self):
        os.chdir(self.old_cwd)
        self.tmp.cleanup()

    def run_cli(self, args):
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = tally.main(["tally.py", *args])
        return code, err.getvalue()

    def test_same_rejection_everywhere(self):
        for name in BAD:
            messages = set()
            for label, build in COMMANDS.items():
                code, err = self.run_cli(build(name))
                self.assertEqual(code, 1, (label, name))
                messages.add(err)
            self.assertEqual(len(messages), 1, name)
            self.assertIn("invalid category", messages.pop())
        self.assertFalse(os.path.exists("ledger.json"))
        self.assertFalse(os.path.exists("budgets.json"))
        self.assertFalse(os.path.exists("recurring.json"))

    def test_valid_name_accepted_everywhere(self):
        for label, build in COMMANDS.items():
            code, _ = self.run_cli(build("car-2"))
            self.assertEqual(code, 0, label)


if __name__ == "__main__":
    unittest.main()
